#include "viewport_fit_candidate.h"
#include <iostream>
void check(bool ok){if(!ok)throw std::runtime_error("viewport fit assertion");}
int main(){auto a=viewportFitCandidate(512,512,624,601);check(a.x==11&&a.y==0&&a.width==601&&a.height==601);auto b=viewportFitCandidate(1920,1080,1000,1000);check(b.width==1000&&b.height==562&&b.y==219);auto c=viewportFitCandidate(1080,1920,1000,1000);check(c.width==562&&c.height==1000&&c.x==219);for(uint32_t sw:{1u,17u,512u,1920u})for(uint32_t sh:{1u,19u,512u,1080u})for(uint32_t dw:{64u,601u,1920u})for(uint32_t dh:{64u,624u,1080u}){if(uint64_t(dw)*sh<sw||uint64_t(dh)*sw<sh)continue;auto r=viewportFitCandidate(sw,sh,dw,dh);check(r.x>=0&&r.y>=0&&uint32_t(r.x+r.width)<=dw&&uint32_t(r.y+r.height)<=dh);check(uint32_t(r.width)==dw||uint32_t(r.height)==dh);auto residual=int64_t(r.width)*sh-int64_t(r.height)*sw;check(residual<=int64_t(sw)&&residual>=-int64_t(sh));}bool bad=false;try{viewportFitCandidate(0,1,10,10);}catch(...){bad=true;}check(bad);std::cout<<"viewport fit passed: square, landscape, portrait, bounded extents, one-pixel aspect rounding, invalid extent\n";}
